#!/bin/sh
# W71 phase 2 follow-ups: the PT metrics' first call came back empty (a warm-up config first now), timings with ?timing,
# streaks / stripes without RT at a fixed frame index, the carConcept / chess grazing sweep.
A=${A:-5443}; OUT=$1; D=$(dirname "$0"); mkdir -p "$OUT"
B="http://127.0.0.1:$A/showcase/bench.html?manual&left=ours-denoised&right=pathtraced"
node "$D/drive.mjs" "$B&scene=lineSpreadThin" "$OUT" "$D/p2-bench.js" "const TAG='thick-lineSpreadThin2'; const CONFIGS=[{name:'warm',set:{}},{name:'k0',set:{}},{name:'rel0.01',set:{'s.thicknessDepthFactor':0.01,'s.thicknessDepthMode':'relative'}},{name:'rel0.005',set:{'s.thicknessDepthFactor':0.005,'s.thicknessDepthMode':'relative'}}]; const PT={fn:'lineSpread',opts:{scene:'lineSpreadThin',roughness:[0.05,0.15,0.3],methods:['ours-raw','ours-denoised','ours-rt']}};" > "$OUT/thick-lineSpreadThin2.log" 2>&1
node "$D/drive.mjs" "$B&scene=lineSpread" "$OUT" "$D/p2-bench.js" "const TAG='thick-lineSpread'; const CONFIGS=[{name:'warm',set:{}},{name:'k0',set:{}},{name:'rel0.01',set:{'s.thicknessDepthFactor':0.01,'s.thicknessDepthMode':'relative'}},{name:'rel0.025',set:{'s.thicknessDepthFactor':0.025,'s.thicknessDepthMode':'relative'}}]; const PT={fn:'lineSpread',opts:{roughness:[0.05,0.15],methods:['ours-raw','ours-denoised','ours-rt']}};" > "$OUT/thick-lineSpread.log" 2>&1
node "$D/drive.mjs" "$B&scene=lineSpread" "$OUT" "$D/p2-bench.js" "const TAG='graz-lineSpread2'; const CONFIGS=[{name:'warm',set:{}},{name:'g0',set:{}},{name:'g1',set:{'s.hitLobeFilterGrazing':1}}]; const PT={fn:'lineSpread',opts:{roughness:[0.05,0.15,0.3],methods:['ours-raw','ours-denoised','ours-rt'],settings:{aa:'off'}}};" > "$OUT/graz-lineSpread2.log" 2>&1
for u in mirrorWall contact rooms; do
  node "$D/drive.mjs" "http://127.0.0.1:$A/ssr/?manual&scene=$u&aa=off" "$OUT" "$D/p2-ssr.js" "const TAG='thick-ssr0-$u'; const CONFIGS=[{name:'k0',set:{frameIndex:7}},{name:'k0.01',set:{frameIndex:7,thicknessDepthFactor:0.01}},{name:'k0.02',set:{frameIndex:7,thicknessDepthFactor:0.02}},{name:'rel0.01',set:{frameIndex:7,thicknessDepthFactor:0.01,thicknessDepthMode:'relative'}},{name:'rel0.025',set:{frameIndex:7,thicknessDepthFactor:0.025,thicknessDepthMode:'relative'}},{name:'rel0.05',set:{frameIndex:7,thicknessDepthFactor:0.05,thicknessDepthMode:'relative'}}]; const WHICH=[]; const OPTS={}; const STATS=true;" > "$OUT/thick-ssr0-$u.log" 2>&1
done
T="const ROUNDS=3, N=30;"
node "$D/drive.mjs" "http://127.0.0.1:$A/ssr/?manual&timing&scene=contact&rt=1&w=1920&h=1080&aa=off" "$OUT" "$D/p2-time.js" "const TAG='time-contact-1080'; $T const CONFIGS=[{name:'default',set:{}},{name:'pattern',set:{quadBaseRotation:'pattern'}},{name:'k0.01',set:{thicknessDepthFactor:0.01}},{name:'rel0.01',set:{thicknessDepthFactor:0.01,thicknessDepthMode:'relative'}},{name:'graz1',set:{hitLobeFilterGrazing:1}}];" > "$OUT/time-contact.log" 2>&1
node "$D/drive.mjs" "http://127.0.0.1:$A/ssr/?manual&timing&scene=mirrorWall&rt=1&w=1920&h=1080&aa=off&hit=final&reshade=off" "$OUT" "$D/p2-time.js" "const TAG='time-mirrorWall-1080-history'; $T const CONFIGS=[{name:'default',set:{}},{name:'edge',set:{historyEdgeConfidence:true}}];" > "$OUT/time-mirrorWall.log" 2>&1
echo done
